#include "BrowserComponent.h"
#include "../PluginProcessor.h"
namespace {
const juce::StringArray categories{"VOCALS","SOUL","R&B","MEMPHIS","PHONK","POP","INDIE","HORROR","RETRO GAME","CHIPTUNE","WORLD","SYNTH","BASS","PADS","KEYS","FX"};
}
LibraryBrowser::LibraryBrowser(GBoyProcessor& p,std::function<int()> target):processor(p),layer(std::move(target)){
 query.setTextToShowWhenEmpty("Search name, tags, author, license, language or tradition...",juce::Colours::grey);query.onTextChange=[this]{refresh();};addAndMakeVisible(query);
 category.addItem("All categories",1);category.addItemList(categories,2);category.setSelectedId(1);kind.addItemList({"All types","Samples","Patches","FX racks","Patterns"},1);kind.setSelectedId(1);category.onChange=[this]{refresh();};kind.onChange=[this]{refresh();};libraries.onChange=[this]{refresh();};
 for(auto* component:{&category,&kind,&libraries,&editCategory})addAndMakeVisible(component);editCategory.addItemList(categories,1);editCategory.setEditableText(true);
 for(auto* component:{&favorites,&favorite})addAndMakeVisible(component);favorites.onClick=[this]{refresh();};favorite.onClick=[this]{const auto e=selected();if(e.id.isNotEmpty())processor.library.favorite(e.id,favorite.getToggleState());};
 for(auto* editor:{&tags,&author,&license,&provenance})addAndMakeVisible(editor);
 root.setRange(0,127,1);root.setSliderStyle(juce::Slider::LinearHorizontal);root.setTextBoxStyle(juce::Slider::TextBoxRight,false,45,24);addAndMakeVisible(root);
 for(auto* label:{&details,&status,&help,&tagLabel,&authorLabel,&licenseLabel,&sourceLabel,&rootLabel})addAndMakeVisible(label);details.setJustificationType(juce::Justification::topLeft);details.setFont(13);tagLabel.setText("Tags / category",juce::dontSendNotification);authorLabel.setText("Author",juce::dontSendNotification);licenseLabel.setText("License",juce::dontSendNotification);sourceLabel.setText("Provenance",juce::dontSendNotification);rootLabel.setText("Root MIDI (on load)",juce::dontSendNotification);
 for(auto* button:{&load,&preview,&stop,&similar,&clearSimilar,&saveMetadata,&add,&folder,&install,&relocate,&rescan,&exportPack,&savePatch})addAndMakeVisible(button);
 load.onClick=[this]{const auto e=selected();if(!processor.loadLibraryEntry(e.id,layer()))status.setText("Cannot load: missing/invalid asset or unbundled patch dependency",juce::dontSendNotification);};preview.onClick=[this]{processor.previewLibraryEntry(selectedId);};stop.onClick=[this]{processor.stopLibraryPreview();};similar.onClick=[this]{similarId=selectedId;refresh();};clearSimilar.onClick=[this]{similarId.clear();refresh();};
 saveMetadata.onClick=[this]{processor.library.edit(selectedId,editCategory.getText(),tags.getText(),author.getText(),license.getText(),provenance.getText(),int(root.getValue()));};
 add.onClick=[this]{choose(0);};folder.onClick=[this]{choose(1);};install.onClick=[this]{choose(2);};relocate.onClick=[this]{choose(3);};exportPack.onClick=[this]{choose(4);};savePatch.onClick=[this]{choose(5);};rescan.onClick=[this]{processor.library.rescan();};
 list.setModel(this);list.setRowHeight(48);list.setColour(juce::ListBox::backgroundColourId,juce::Colour(0xff15212a));addAndMakeVisible(list);
 help.setText("Import copies files; Add folder links originals. Samples: WAV/AIFF/FLAC, max 30s. Packs: gboy-library.json folder. Preview uses a separate player. Acoustic analysis is heuristic; edit root/tags before loading. Human/language/style metadata is never inferred.",juce::dontSendNotification);help.setFont(12);refresh(true);startTimerHz(5);
}
LibraryBrowser::~LibraryBrowser(){stopTimer();processor.stopLibraryPreview();list.setModel(nullptr);}
void LibraryBrowser::paint(juce::Graphics& g){g.fillAll(juce::Colour(0xff202b3c));}
void LibraryBrowser::resized(){const int w=getWidth(),left=w*43/100,right=left+15,rw=w-right-10;
 query.setBounds(10,8,w-20,28);category.setBounds(10,43,180,26);kind.setBounds(200,43,140,26);libraries.setBounds(350,43,std::max(170,w-530),26);favorites.setBounds(w-165,43,160,26);
 list.setBounds(10,78,left-10,getHeight()-185);details.setBounds(right,78,rw,78);favorite.setBounds(right,159,100,26);load.setBounds(right+110,159,rw-110,26);
 preview.setBounds(right,192,rw/3-6,26);stop.setBounds(right+rw/3,192,rw/3-6,26);similar.setBounds(right+rw*2/3,192,rw/3,26);
 tagLabel.setBounds(right,225,110,23);tags.setBounds(right+112,225,rw-112,23);editCategory.setBounds(right,253,145,23);authorLabel.setBounds(right+155,253,55,23);author.setBounds(right+210,253,rw-210,23);
 licenseLabel.setBounds(right,281,105,23);license.setBounds(right+112,281,rw-112,23);sourceLabel.setBounds(right,309,105,23);provenance.setBounds(right+112,309,rw-112,23);rootLabel.setBounds(right,338,145,23);root.setBounds(right+150,338,rw-150,23);
 saveMetadata.setBounds(right,370,rw/2-5,27);clearSimilar.setBounds(right+rw/2,370,rw/2,27);
 const int y=getHeight()-94,bw=(w-20)/7;juce::TextButton* buttons[]={&add,&folder,&install,&relocate,&rescan,&exportPack,&savePatch};for(int i=0;i<7;++i)buttons[i]->setBounds(10+i*bw,y,bw-5,28);status.setBounds(10,y+33,w-20,23);help.setBounds(10,y+55,w-20,39);
}
void LibraryBrowser::paintListBoxItem(int row,juce::Graphics& g,int w,int h,bool isSelected){if(row<0||row>=int(results.size()))return;const auto& e=results[size_t(row)];if(isSelected)g.fillAll(juce::Colour(0xff426255));g.setColour(juce::Colour(e.missing?0xffffb0ac:0xff9de5c6));
 if(e.analysed){juce::Path path;for(size_t i=0;i<64;++i){const float x=5+float(i),y=24-e.analysis.waveform[i]*18;if(i==0)path.startNewSubPath(x,y);else path.lineTo(x,y);}g.strokePath(path,juce::PathStrokeType(1));}else{for(int x=0;x<4;++x)for(int y=0;y<4;++y)if(((e.id.hashCode()>>(x+y*4))&1)!=0)g.fillRect(10+x*10,5+y*10,8,8);}
 g.setFont(15);g.drawText((e.favorite?"* ":"")+e.name+(e.missing?" [MISSING]":""),76,3,w-82,23,juce::Justification::centredLeft);g.setFont(11);g.drawText(e.category+" / "+e.kind+" / "+(e.libraryId=="factory"?"Factory":"User library"),76,26,w-82,h-27,juce::Justification::centredLeft);
}
gboy::library::Entry LibraryBrowser::selected() const {for(const auto& e:results)if(e.id==selectedId)return e;return {};}
void LibraryBrowser::selectedRowsChanged(int row){if(row>=0&&row<int(results.size()))selectedId=results[size_t(row)].id;else selectedId.clear();selection();}
void LibraryBrowser::listBoxItemDoubleClicked(int row,const juce::MouseEvent&){if(row>=0&&row<int(results.size()))processor.loadLibraryEntry(results[size_t(row)].id,layer());}
void LibraryBrowser::selection(){const auto e=selected();const bool valid=e.id.isNotEmpty(),editable=valid&&e.action=="file";favorite.setEnabled(valid);favorite.setToggleState(e.favorite,juce::dontSendNotification);load.setEnabled(valid&&!e.missing);const bool canPreview=valid&&!e.missing&&(e.kind=="sample"||e.action=="hybrid"||e.action=="vocal"||e.preview.isNotEmpty());preview.setEnabled(canPreview);similar.setEnabled(valid&&e.kind=="sample"&&e.analysed);saveMetadata.setEnabled(editable);for(auto* editor:{&tags,&author,&license,&provenance})editor->setEnabled(editable);root.setEnabled(editable&&e.kind=="sample");editCategory.setEnabled(editable);
 tags.setText(e.tags,false);author.setText(e.author,false);license.setText(e.license,false);provenance.setText(e.provenance,false);editCategory.setText(e.category,juce::dontSendNotification);root.setValue(e.root,juce::dontSendNotification);
 auto text=e.name+" / "+e.kind+"\n"+e.description+"\n"+e.license+" | "+e.human;if(e.language.isNotEmpty()||e.tradition.isNotEmpty())text+="\n"+e.language+" / "+e.tradition+" / "+e.region;
 if(e.analysed)text+="\n"+juce::String(e.analysis.seconds,2)+" s | pitch "+(e.analysis.pitchHz>0?juce::String(e.analysis.pitchHz,1)+" Hz":"uncertain")+" | BPM "+(e.analysis.bpm>0?juce::String(e.analysis.bpm,1):"uncertain")+" | "+juce::String(int(e.analysis.transients.size()))+" onsets";
 text+="\n"+(e.action=="file"?e.path:e.provenance);details.setText(valid?text:"Select a sound or import original/licensed content.",juce::dontSendNotification);details.setTooltip(text);clearSimilar.setEnabled(similarId.isNotEmpty());
}
void LibraryBrowser::refresh(bool menus){snapshot=processor.library.snapshot();revision=snapshot.revision;if(menus){const auto old=libraries.getText();libraries.clear(juce::dontSendNotification);libraries.addItem("All libraries",1);libraries.addItem("Factory",2);int id=3;for(const auto& root:snapshot.roots)libraries.addItem(root.name,id++);libraries.setSelectedId(1,juce::dontSendNotification);for(int i=0;i<libraries.getNumItems();++i)if(libraries.getItemText(i)==old)libraries.setSelectedItemIndex(i,juce::dontSendNotification);}
 gboy::library::Query q;q.text=query.getText();q.category=category.getSelectedId()>1?category.getText():juce::String{};const char* kinds[]={"","sample","patch","rack","pattern"};q.kind=kinds[juce::jlimit(0,4,kind.getSelectedId()-1)];const int lib=libraries.getSelectedId();if(lib==2)q.libraryId="factory";else if(lib>=3&&lib-3<int(snapshot.roots.size()))q.libraryId=snapshot.roots[size_t(lib-3)].id;q.favorites=favorites.getToggleState();q.similarTo=similarId;results=gboy::library::search(snapshot,q);
 const auto keep=selectedId;list.updateContent();int row=-1;for(size_t i=0;i<results.size();++i)if(results[i].id==keep)row=int(i);if(row>=0)list.selectRow(row);else{list.deselectAllRows();selectedId.clear();}selection();status.setText((snapshot.busy?"WORKING / ":"")+snapshot.status+" / "+juce::String(int(results.size()))+" results"+(similarId.isNotEmpty()?" / SIMILARITY SORT":""),juce::dontSendNotification);
}
void LibraryBrowser::timerCallback(){const auto current=processor.library.snapshot();if(current.revision!=revision)refresh(current.roots.size()!=snapshot.roots.size());preview.setButtonText(processor.previewBusy.load()?"RENDERING...":"PREVIEW");}
bool LibraryBrowser::isInterestedInFileDrag(const juce::StringArray& files){if(files.isEmpty())return false;for(const auto& path:files)if(!juce::File(path).hasFileExtension("wav;aif;aiff;flac;gboy;gbfx"))return false;return true;}
void LibraryBrowser::filesDropped(const juce::StringArray& files,int,int){if(!isInterestedInFileDrag(files))return;std::vector<juce::File> input;for(const auto& path:files)input.emplace_back(path);processor.library.importFiles(std::move(input));}
void LibraryBrowser::choose(int action){const bool directory=action>=1&&action<=4;const auto libraryId=libraries.getSelectedId()>=3&&libraries.getSelectedId()-3<int(snapshot.roots.size())?snapshot.roots[size_t(libraries.getSelectedId()-3)].id:juce::String{};
 if((action==3||action==4)&&libraryId.isEmpty()){status.setText("Select a user/installed library in the library filter first",juce::dontSendNotification);return;}
 const char* titles[]={"Batch import original or licensed content","Link sample/preset folder","Install pack: choose folder containing gboy-library.json","Select new root for this library","Create exported library folder","Save current full patch and add to browser"};chooser=std::make_unique<juce::FileChooser>(titles[action],juce::File{},directory?"*":action==5?"*.gboy":"*.wav;*.aif;*.aiff;*.flac;*.gboy;*.gbfx");int flags=(action==4||action==5)?juce::FileBrowserComponent::saveMode|juce::FileBrowserComponent::warnAboutOverwriting:juce::FileBrowserComponent::openMode;flags|=directory?juce::FileBrowserComponent::canSelectDirectories:juce::FileBrowserComponent::canSelectFiles;if(action==0)flags|=juce::FileBrowserComponent::canSelectMultipleItems;
 chooser->launchAsync(flags,[safe=juce::Component::SafePointer<LibraryBrowser>(this),action,libraryId](const juce::FileChooser& chooser){if(!safe)return;const auto file=chooser.getResult();if(file==juce::File{})return;if(action==0){std::vector<juce::File> files;for(const auto& f:chooser.getResults())files.push_back(f);safe->processor.library.importFiles(std::move(files));}else if(action==1)safe->processor.library.scanFolder(file);else if(action==2)safe->processor.library.installPack(file);else if(action==3)safe->processor.library.relocate(libraryId,file);else if(action==4)safe->processor.library.exportLibrary(libraryId,file);else if(!safe->processor.saveLibraryPatch(file))safe->status.setText("Cannot save patch",juce::dontSendNotification);});
}
